{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect specification document and feature change list",
        "actor": "Document Reviewer",
        "system": "Document Repository",
        "inputs": [
          "New version of specification document",
          "Feature change list"
        ],
        "outputs": [
          "Collected specification document",
          "Collected feature change list"
        ]
      },
      {
        "id": "A2",
        "name": "Compare feature changes against document content",
        "actor": "Document Reviewer",
        "system": "Document Repository, Review Checklist",
        "inputs": [
          "Collected specification document",
          "Collected feature change list",
          "Previous document version",
          "Review checklist"
        ],
        "outputs": [
          "List of discrepancies or missing features"
        ]
      },
      {
        "id": "A3",
        "name": "Check terminology and formatting consistency",
        "actor": "Document Reviewer",
        "system": "Review Checklist, Commenting Tool",
        "inputs": [
          "Collected specification document",
          "Review checklist"
        ],
        "outputs": [
          "List of terminology and formatting issues"
        ]
      },
      {
        "id": "A4",
        "name": "Record review comments and change request list",
        "actor": "Document Reviewer",
        "system": "Commenting Tool",
        "inputs": [
          "List of discrepancies or missing features",
          "List of terminology and formatting issues"
        ],
        "outputs": [
          "Review comments",
          "Change request list"
        ]
      },
      {
        "id": "A5",
        "name": "Revise specification document",
        "actor": "Document Author",
        "system": "Document Repository, Commenting Tool",
        "inputs": [
          "Review comments",
          "Change request list"
        ],
        "outputs": [
          "Revised specification document"
        ]
      },
      {
        "id": "A6",
        "name": "Confirm revisions are acceptable",
        "actor": "Feature Owner",
        "system": "Unknown",
        "inputs": [
          "Revised specification document",
          "Change request list"
        ],
        "outputs": [
          "Confirmation decision (acceptable or not acceptable)"
        ]
      },
      {
        "id": "A7",
        "name": "Issue formal approval of final document",
        "actor": "Approver",
        "system": "Unknown",
        "inputs": [
          "Confirmed revised specification document"
        ],
        "outputs": [
          "Approval decision",
          "Updated and approved specification document"
        ]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are the revisions confirmed as acceptable by the Feature Owner?",
        "branches": [
          {
            "outcome": "Acceptable",
            "next": "A7"
          },
