        "type": "control_flow"
      },
      {
        "from": "D1",
        "to": "A7",
        "type": "control_flow"
      }
    ]
  },
  "automation_opportunities": [
    {
      "target": "A1 - Collect specification document and feature change list",
      "rationale": "Availability of a new document version and feature change list can be detected automatically in a document repository, triggering collection and notification to the reviewer without manual polling.",
      "required_data": [
        "Document version metadata",
        "Feature change list availability status",
        "Reviewer assignment information"
      ],
      "constraints": [
        "Trigger mechanism for change list availability is not yet specified",
        "Document repository must support event-based notifications"
      ],
      "confidence": "medium"
    },
    {
      "target": "A2 - Compare feature changes against document content",
      "rationale": "Structured diff tools or NLP-based comparison can automatically flag sections of the document that do not reflect items in the feature change list, reducing manual reading effort.",
      "required_data": [
        "Machine-readable feature change list",
        "Structured or tagged specification document",
        "Previous document version"
      ],
      "constraints": [
        "Requires documents to be in a structured or parseable format",
        "Accuracy depends on quality of feature change list granularity"
      ],
      "confidence": "medium"
    },
    {
      "target": "A3 - Check terminology and formatting consistency",
      "rationale": "Automated linting tools and terminology checkers can scan documents for formatting violations and non-standard terminology against a defined glossary or style guide.",
      "required_data": [
        "Approved terminology glossary",
        "Formatting and style rules",
        "Specification document in parseable format"
      ],
      "constraints": [
