      "required_data": [
        "Change request list with item-level tracking",
        "Feature Owner response per item"
      ],
      "constraints": [
        "Final confirmation decision still requires human judgment",
        "System to capture Feature Owner responses is not yet specified"
      ],
      "confidence": "low"
    }
  ],
